pub enum MailboxLaneRegistration {
    #[graphql(name = "SEEDED")]
    SEEDED,
    #[graphql(name = "DECLARED_UNSEEDED")]
    DECLARED_UNSEEDED,
    #[graphql(name = "UNDECLARED_ORPHAN")]
    UNDECLARED_ORPHAN,
}
